    // 2) 이름으로 파생
    List<Member> findByUsername(String username);

    // 3) @Query
    @Query("select m from Member m where m.age > :age")
    List<Member> findOlderThan(@Param("age") int age);

    // 4) default 메서드
    default String describe() {
        return "회원 " + count() + "명";
    }
}

